import { forwardRef, useState, useEffect, useMemo, useCallback, Suspense, type ReactNode, type ChangeEvent } from 'react'
import './screenmate-one-order.scss'
import { useAppDispatch, useAppSelector } from '../../redux/hooks'
import { fetchProducts } from '../../redux/selectors/products'
import { fetchOrder } from '../../redux/selectors/order'
import { fetchContent } from '../../redux/selectors/content'
import type { Model } from '../../types/product'

import SlickSlider, { type Settings } from '../Common/SlickSlider'
import Button from '../Common/Button'
import Icon from '../Common/Icon'
import Image from '../Common/Image'
import Dropdown, { type DropdownOption } from '../Common/Dropdown'
import chevronLeft from '@/assets/icons/chevron-white-left.svg'
import chevronRight from '@/assets/icons/chevron-white-right.svg'
import global from '@/assets/icons/global.svg'
import eu from '@/assets/icons/eu.svg'
import shipping from '@/assets/icons/shipping.svg'
import warranty from '@/assets/icons/warranty.svg'

import { mapSimpleConfigs, useAnime, type AnimatedObjectOptions } from '../../hooks/anime'
import { useInlineStyles } from '../../hooks/inline-styles'
import { useDynamicSlice } from '../../hooks/dynamic-slice'
import { useLazyData } from '../../hooks/lazy-data'

const animatedObjects: Record<string, AnimatedObjectOptions> = {
    slider: { yFrom: '20px', duration: 333 },
    name: { yFrom: '40px', duration: 666 },
    prices: { yFrom: '20px', duration: 333 },
    info: { yFrom: '20px', duration: 333 },
    models: { yFrom: '20px', duration: 333 },
    additionals: { yFrom: '20px', duration: 333 },
    button: { yFrom: '40px', duration: 666 },
    details: { yFrom: '20px', duration: 333 },
}

const imageModules: Record<string, any> = import.meta.glob('@/assets/images/screenmate-one/gallery/*-original.{png,jpg,jpeg,svg}', { eager: true })
const thumbModules: Record<string, any> = import.meta.glob('@/assets/images/screenmate-one/gallery/*-thumb.{png,jpg,jpeg,svg}', { eager: true })
const galleryImages: string[] = Object.values(imageModules).map(mod => mod.default)
const galleryThumbs: string[] = Object.values(thumbModules).map(mod => mod.default)

const shopifyUrl: string = import.meta.env.VITE_SHOPIFY_URL || 'http://localhost:5173'

const ScreenmateOneOrder = forwardRef<HTMLDivElement, {}>(({}, ref) => {
    const dispatch = useAppDispatch()

    const { isMobile } = useInlineStyles()

    const { getRate, addToCart } = useDynamicSlice('order', () => import('../../redux/slices/order'))
    const { product, additionalProducts } = useAppSelector(fetchProducts)
    const { rate, addedToCart } = useAppSelector(fetchOrder)
    const { country } = useAppSelector(fetchContent)
    
    const lazyParams = useMemo(() => ({
        action: getRate ? () => getRate('USD/EUR') : () => {},
        selector: '.screenmate-one__order'
    }), [getRate])
    
    useLazyData(lazyParams)

    const [currentImageIndex, setCurrentImageIndex] = useState<number>(0)
    
    const sliderSettings: Settings = useMemo(() => ({
        dots: false,
        infinite: true,
        arrows: true,
        speed: 500,
        slidesToShow: !isMobile ? 6 : 4,
        slidesToScroll: 1,
        swipeToSlide: true,
        prevArrow: <div><Icon icon={chevronLeft} /></div>,
        nextArrow: <div><Icon icon={chevronRight} /></div>,
        beforeChange: (_, next) => setCurrentImageIndex(next)
    }), [isMobile])

    const options: DropdownOption[] = (product?.models || []).flatMap(({ id, title }) =>
        title.split('|').map((model) => ({ label: model.trim(), value: id }))
    )

    const [selectedModel, setSelectedModel] = useState<Model | null>(null)
    const [error, setError] = useState<boolean>(false)

    const handleModelSelect = (modelId: number) => {
        setError(false)
        const model = product?.models?.find(({ id }) => id === modelId) || null
        setSelectedModel(model)
    }

    const currency: string = useMemo(() => country?.currency_code || 'USD', [country])
    // const currency: string = 'USD'

    const coef: number = useMemo(() => currency === 'EUR' ? (rate || 1) : 1, [currency, rate])

    const prices: { current?: number | null; old?: number | null } = useMemo(() => {
        let current = null, old = null
        if (product) {
            current = product.maxPrice
            old = product.oldPrice
            if (selectedModel) {
                current = selectedModel.price
                old = selectedModel.oldPrice
            }
        }
        return { current: (current || 0) * coef, old: (old || 0) * coef }
    }, [product, selectedModel, coef])

    const tax: number = useMemo(() => country?.vat_percent || 20, [country])

    const additionals = useMemo(() => additionalProducts?.map(({ price, ...item }) => ({
        ...item,
        price: (price || 0) * coef
    })), [additionalProducts, coef])

    const showCurrency: string = useMemo(() => coef === 1 ? 'USD' : currency, [coef, currency])

    const [selectedAdditionals, setSelectedAdditionals] = useState<number[]>([])

    const handleAdditionalSelect = (e: ChangeEvent<HTMLInputElement>, additionalId: number | null) => {
        if (additionalId) {
            const { checked } = e.target
            setSelectedAdditionals(prev => checked ? [ ...prev, additionalId ] : prev.filter(id => id !== additionalId))
        }
    }

    const showVAT = useCallback((price?: number | null) => showCurrency === 'EUR' ? (
        <>+{((price || 0) * tax / 100).toFixed(0)} EUR (VAT {tax}%)</>
    ) : <></>, [showCurrency, tax])

    const details: { icon?: string, main?: string, add?: string }[] = useMemo(() => [
        country?.iso_code === 'US' ? {
            icon: shipping, main: 'Free shipping', add: !isMobile ? 'within the United States' : 'for the U.S.'
        } : {},
        { icon: warranty, main: '3-year full warranty', add: 'for Screenmate ONE' },
    ].filter(({ icon, main, add }) => !!icon && !!main && !!add), [country, isMobile])

    const handleSubmit = useCallback(() => {
        if (selectedModel) {
            const items = [
                { id: selectedModel.id, quantity: 1 },
                ...selectedAdditionals.filter(Boolean).map(id => ({ id, quantity: 1 }))
            ]
            dispatch(addToCart({ items }))
        } else {
            setError(true)
        }
    }, [selectedModel, selectedAdditionals, dispatch, addToCart])

    useEffect(() => {
        if (addedToCart && typeof window !== 'undefined') {
            window.open(`${shopifyUrl}/cart`, '_blank')
        }
    }, [addedToCart])

    const animationConfigs = useMemo(() => mapSimpleConfigs(animatedObjects), [])
        
    const { anime } = useAnime(animationConfigs)

    const thumbsList: ReactNode = useMemo(() => galleryThumbs.map((image, index) => (
        <div className="screenmate-one__order-gallery-slider-item-wrap" key={index}>
            <Image                                    
                className={`screenmate-one__order-gallery-slider-item ${
                    currentImageIndex === index ? 'active' : ''
                }`}
                src={image}
                onClick={() => setCurrentImageIndex(index)}
            />
        </div>
    )), [galleryThumbs, currentImageIndex, setCurrentImageIndex])

    return (
        <div ref={ref} className="screenmate-one__order">
            <div className="screenmate-one__order-gallery">
                {galleryImages.map((image, index) => (
                    <img
                        key={index}
                        className={`object-cover ${index === currentImageIndex ? '' : 'hidden'}`}
                        src={image}
                        alt={`Screenmate ONE device and installation cables${index !== 0 ? ` ${index}` : ''}`}
                    />
                ))}
                <div {...anime('slider')} className="screenmate-one__order-gallery-slider-wrap">
                    {import.meta.env.SSR ? (<>
                        {thumbsList}
                    </>) : (
                        <Suspense>
                            <SlickSlider className="screenmate-one__order-gallery-slider" {...sliderSettings}>
                                {thumbsList}
                            </SlickSlider>
                        </Suspense>
                    )}
                </div>
            </div>
            {product && (
                <div className="screenmate-one__order-form">
                    <div className="screenmate-one__order-form-wrap">
                        <div>
                            <h2 {...anime('name')} className="screenmate-one__order-form-name">{product.title}</h2>
                            <div {...anime('prices')} className="screenmate-one__order-form-prices">
                                <span className="screenmate-one__order-form-prices-current">{prices.current?.toFixed(0) || 0} {showCurrency}</span>
                                {(prices.old || 0) > (prices.current || 0) && (
                                    <span className="screenmate-one__order-form-prices-old">{prices.old?.toFixed(0) || 0} {showCurrency}</span>
                                )}
                            </div>
                            <div {...anime('info')}>
                                {currency === 'USD' && (
                                    // <div className="screenmate-one__order-form-note">
                                    //     Taxes and shipping calculated at checkout
                                    // </div>
                                    <div className="screenmate-one__order-form-notes">
                                        <div>
                                            <Icon icon={global} />
                                            <span>Global prices are shown in USD, VAT not included</span>
                                        </div>
                                        <div>
                                            <Icon icon={eu} />
                                            <span>To see VAT-inclusive pricing select your EU country in the Menu</span>
                                        </div>
                                    </div>
                                )}
                                {currency === 'EUR' && (
                                    <div className="screenmate-one__order-form-vat">{showVAT(prices.current)}</div>
                                )}
                            </div>
                        </div>
                        <div>
                            <Dropdown
                                {...anime('models')}
                                placeholder="Select your Tesla model and year"
                                {...{options, error}}
                                onSelect={(modelId) => handleModelSelect(modelId as number)}
                            />
                            {additionals && (
                                <div {...anime('additionals')} className="screenmate-one__order-form-additionals">
                                    {additionals.map(({ id, title, price, models }) => {
                                        const modelId = models ? models[0].id : null
                                        return (
                                            <div key={id}>
                                                <input
                                                    type="checkbox"
                                                    id={`additional-product-${id}`}
                                                    checked={modelId !== null && selectedAdditionals.includes(modelId)}
                                                    onChange={(e) => handleAdditionalSelect(e, modelId)}
                                                />
                                                <label htmlFor={`additional-product-${id}`}>
                                                    <span>Add {title}</span>&nbsp;
                                                    <span>{price?.toFixed(0) || 0} {showCurrency} {showVAT(price)}</span>
                                                </label>
                                            </div>
                                        )
                                    })}
                                </div>
                            )}
                        </div>
                        <div>
                            <Button {...anime('button')} onClick={handleSubmit}>
                                <span>order now</span>
                            </Button>
                            <div {...anime('details')} className="screenmate-one__order-form-details">
                                {details.map(({ icon, main, add }, index) => (
                                    <div className="screenmate-one__order-form-details-item" key={index}>
                                        <Icon {...{icon}} />
                                        <span>
                                            <span>{main}</span>&nbsp;
                                            <span>{add}</span>
                                        </span>
                                    </div>
                                ))}
                                {selectedModel?.sku === 'TS12' && (
                                    <div className="screenmate-one__order-form-details-delivery">
                                        Estimated delivery: <span>November</span>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    )
})

export default ScreenmateOneOrder
